import React, { useState } from "react";
import { motion } from "framer-motion";
import { Calendar, ArrowRight } from "lucide-react";

export default function EventDate() {
  const [eventDate, setEventDate] = useState("");
  const [eventType, setEventType] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (eventDate) {
      const message = `*Event Reminder Request - D SAJAWAT*\n\n*Event Type:* ${eventType}\n*Event Date:* ${eventDate}\n\nHi! I'd like to plan my fabric order for this event. Please contact me with availability.`;
      window.open(`https://wa.me/919888919983?text=${encodeURIComponent(message)}`, "_blank");
    }
  };

  return (
    <section className="relative py-20 md:py-28" style={{ background: "linear-gradient(135deg, #1a080a 0%, #2a1015 100%)" }}>
      {/* Decorative Gold Lines */}
      <div className="absolute top-0 left-0 w-full h-1" style={{ background: "linear-gradient(90deg, transparent, #d4af37, transparent)" }} />

      <div className="px-6 md:px-12 lg:px-24 max-w-4xl mx-auto text-center">

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full mb-6" style={{ background: "rgba(212,175,55,0.15)", border: "1px solid rgba(212,175,55,0.3)" }}>
            <Calendar size={16} color="#d4af37" />
            <span className="text-xs uppercase tracking-wider" style={{ color: "#d4af37" }}>Plan Your Event</span>
          </div>

          <h2 className="serif text-3xl md:text-5xl mb-4" style={{ color: "#ffffff" }}>
            When's Your <span className="gold-shimmer">Big Day</span>?
          </h2>

          <p className="text-base md:text-lg mb-10 max-w-2xl mx-auto" style={{ color: "rgba(255,255,255,0.7)", lineHeight: 1.7 }}>
            Tell us your event date and we'll help you plan the perfect fabric order. Get personalized recommendations and priority booking!
          </p>

          {/* Date Reminder Form */}
          <form onSubmit={handleSubmit} className="max-w-xl mx-auto">
            <div className="flex flex-col md:flex-row gap-4 justify-center mb-6">
              <select
                value={eventType}
                onChange={(e) => setEventType(e.target.value)}
                className="px-6 py-4 rounded-full text-base"
                style={{ background: "rgba(255,255,255,0.1)", border: "2px solid rgba(212,175,55,0.4)", color: "white", minWidth: "200px" }}
              >
                <option value="">Event Type</option>
                <option value="Wedding">Wedding</option>
                <option value="Engagement">Engagement</option>
                <option value="Ring Ceremony">Ring Ceremony</option>
                <option value="Birthday Party">Birthday Party</option>
                <option value="Corporate Event">Corporate Event</option>
                <option value="Festival">Festival Celebration</option>
                <option value="Other">Other</option>
              </select>

              <input
                type="date"
                value={eventDate}
                onChange={(e) => setEventDate(e.target.value)}
                className="px-6 py-4 rounded-full text-base"
                style={{ background: "rgba(255,255,255,0.1)", border: "2px solid rgba(212,175,55,0.4)", color: "white", minWidth: "200px" }}
              />
            </div>

            <motion.button
              type="submit"
              disabled={!eventDate}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              className="btn-gold text-base md:text-lg px-10 py-4"
              style={{
                opacity: eventDate ? 1 : 0.5,
                cursor: eventDate ? "pointer" : "not-allowed"
              }}
            >
              Book Consultation
              <ArrowRight size={18} />
            </motion.button>
          </form>

          <p className="text-xs mt-6" style={{ color: "rgba(255,255,255,0.4)" }}>
            * Free consultation • Priority booking • Pan India delivery
          </p>
        </motion.div>
      </div>

      {/* Decorative Gold Lines */}
      <div className="absolute bottom-0 left-0 w-full h-1" style={{ background: "linear-gradient(90deg, transparent, #d4af37, transparent)" }} />
    </section>
  );
}
